theorem:
\begin{theorem}\label{thm:dvr}
Let $(R,\mathfrak m)$ be a Noetherian local domain whose only nonzero prime is $\mathfrak m\ne0$. The following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item $R$ is a DVR;
\item $R$ is integrally closed;
\item $\mathfrak m$ is principal;
\item $\mathfrak m$ is invertible.
\end{enumerate}
Moreover, (c) implies (a) in any Noetherian local domain with $\mathfrak m\ne0$, without assuming that it is the only nonzero prime.
\end{theorem}

\begin{theorem}[Noether, 1927]\label{thm:dedekind}
For a Noetherian domain $R$ that is not a field, the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item $R$ is Dedekind;
\item $R_{\mathfrak p}$ is a DVR for every nonzero prime $\mathfrak p$;
\item every fractional ideal is invertible;
\item every nonzero proper ideal is a product of prime ideals.
\end{enumerate}
When these conditions hold, the factorisation in (d) is unique up to rearrangement of its factors.
\end{theorem}

\begin{theorem}\label{thm:intclosure}
Let $R$ be Dedekind with fraction field $K$, and let $L/K$ be finite separable of degree $n$. Write $S$ for the integral closure of $R$ in $L$.
\begin{enumerate}[label=(\alph*)]
\item There is $\theta\in S$ with $L=K(\theta)$. The element
\[
 d=\det\bigl(\operatorname{Tr}_{L/K}(\theta^{i+j})\bigr)_{0\le i,j<n}
\]
is nonzero, belongs to $R$, and satisfies $dS\subseteq R[\theta]$.
\item The ring $S$ is a finitely generated $R$-module and is a Dedekind domain with fraction field $L$.
\end{enumerate}
\end{theorem}

\begin{theorem}[the fundamental identity]\label{thm:fundid}
With these hypotheses and notation, $\displaystyle\sum_{i=1}^g e_i f_i=n$.
\end{theorem}

proposition:
\begin{proposition}[one and a half generators]\label{prop:twogen}
Let $I$ be a nonzero ideal in a Dedekind domain, and choose $0\ne a\in I$. There is $b\in I$ with $I=(a,b)$.
\end{proposition}

lemma:
\begin{lemma}\label{lem:invertible}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item If $IJ=R$, then $J=(R:I)$ and $I$ is finitely generated. We write $I^{-1}=(R:I)$.
\item The product $IJ$ is invertible if and only if each of $I$ and $J$ is invertible.
\item Over a local domain, a fractional ideal is invertible if and only if it is principal.
\item If $I$ is finitely generated, it is invertible if and only if $I_{\mathfrak m}$ is invertible over $R_{\mathfrak m}$ for every maximal ideal $\mathfrak m$.
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:trace}
Let $L/K$ be finite of degree $n$, and let $y\in L$ have minimal polynomial $f\in K[x]$ of degree $d$. The characteristic polynomial of multiplication $m_y\colon z\mapsto yz$ on $L$ is $f^{n/d}$. Its trace is denoted $\operatorname{Tr}_{L/K}(y)$. If $R$ is integrally closed with fraction field $K$ and $y$ is integral over $R$, this characteristic polynomial belongs to $R[x]$ and $\operatorname{Tr}_{L/K}(y)\in R$.
\end{lemma}

corollary:
\begin{corollary}[to contain is to divide]\label{cor:contain}
For fractional ideals $I,J$ of a Dedekind domain, the following are equivalent: $J\subseteq I$; $J=IL$ for some nonzero ideal $L\subseteq R$; and $v_{\mathfrak p}(J)\ge v_{\mathfrak p}(I)$ for every nonzero prime $\mathfrak p$. Moreover,
\[
\begin{split}
 v_{\mathfrak p}(I+J)&=\min(v_{\mathfrak p}(I),v_{\mathfrak p}(J)),\\
 v_{\mathfrak p}(I\cap J)&=\max(v_{\mathfrak p}(I),v_{\mathfrak p}(J)).
\end{split}
\]
\end{corollary}

definition:
\begin{definition}\label{def:dvr}
A \emph{discrete valuation ring}, or DVR, is a principal ideal domain with exactly one nonzero prime ideal.
\end{definition}

\begin{definition}\label{def:dedekind}
A \emph{Dedekind domain} is a Noetherian integrally closed domain that is not a field and whose nonzero prime ideals are all maximal.
\end{definition}

\begin{definition}\label{def:classgroup}
For a Dedekind domain $R$, its \emph{class group} is $\operatorname{Cl}(R)=\mathcal I(R)/\mathcal P(R)$, where $\mathcal P(R)$ is the subgroup of principal fractional ideals. The order of this group, if finite, is the \emph{class number}.
\end{definition}

example:
\begin{example}\label{ex:sixtwice}
In $R=\Z[\sqrt{-5}]$, put $\mathfrak p=(2,1+\sqrt{-5})$, $\mathfrak q=(3,1+\sqrt{-5})$ and $\bar{\mathfrak q}=(3,1-\sqrt{-5})$. This ring is Dedekind, and
\[
\begin{gathered}
 2R=\mathfrak p^2,\qquad 3R=\mathfrak q\bar{\mathfrak q},\\
 (1+\sqrt{-5})R=\mathfrak p\mathfrak q,\qquad
 (1-\sqrt{-5})R=\mathfrak p\bar{\mathfrak q}.
\end{gathered}
\]
None of these three primes is principal. The two element factorizations of $6$ regroup the same prime-ideal factors $\mathfrak p,\mathfrak p,\mathfrak q,\bar{\mathfrak q}$.
\end{example}

exercise_blocks:
\begin{exercise}[$\star$]\label{ex:zsqrt5}
For $R=\Z[\sqrt{-5}]$, verify all four prime-ideal factorizations in Example~\ref{ex:sixtwice} by multiplying generators. Use the multiplicative norm $N(a+b\sqrt{-5})=a^2+5b^2$ to prove that $\mathfrak p=(2,1+\sqrt{-5})$ is not principal.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:powerseries}
Let $k$ be any field. Prove that the formal power series ring $k[[t]]$ is a DVR. Describe its fraction field and its valuation, including the value at a nonzero constant and the convention at zero.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:semilocal}
Suppose a Dedekind domain has only finitely many prime ideals. Prove that it is a PID by constructing a generator for each nonzero prime ideal.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:notdedekind}
Show that $\C[x,y]$ and $\Z[\sqrt{-3}]$ are Noetherian domains but are not Dedekind. In each ring give a nonzero prime ideal that is not invertible, and identify the Dedekind hypothesis that fails.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:circle}
Let $A=\R[x,y]/(x^2+y^2-1)$. You may take for granted that it is Dedekind. Prove that $\mathfrak m=(x-1,y)$ is not principal, although $\mathfrak m^2=(x-1)$. Show that $A\otimes_{\R}\C\cong\C[u,u^{-1}]$ is a PID. The further assertion $\operatorname{Cl}(A)\cong\Z/2$ is quoted, and is not requested or proved here.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:cubicnotprincipal}
In $A=\C[x,y]/(y^2-x^3+x)$, put $N(a+by)=a^2-b^2(x^3-x)$ for $a,b\in\C[x]$.
\begin{enumerate}[label=(\alph*)]
\item Prove that every element has a unique expression $a+by$, that $N$ is multiplicative, and that the units of $A$ are exactly the nonzero constants.
\item For $\mathfrak m=(x,y)$, prove $\mathfrak m^2=(x)$ and show that $\mathfrak m$ is not principal by comparing norm degrees.
\item Give the integral-closure proof for this particular cubic, checking exactly where squarefreeness enters.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch06-arithmetic}
Let $\mathfrak p\ne\mathfrak q$ be nonzero primes of a Dedekind domain. For $I=\mathfrak p^2\mathfrak q$ and $J=\mathfrak p\mathfrak q^3$, compute $I+J$, $I\cap J$, $IJ$ and the fractional colon $(I:J)=\{x\in K:xJ\subseteq I\}$. Identify which of $I,J$ contains the other. Give the corresponding numerical ideals in $\Z$ for $\mathfrak p=(2)$ and $\mathfrak q=(3)$, and describe $R/I$ by the Chinese remainder theorem.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch06-projective}
Let $I$ be an invertible fractional ideal of a domain $R$. Choose $a_i\in I$, $b_i\in I^{-1}$ with $\sum_{i=1}^n a_ib_i=1$. Use these elements to exhibit $I$ as a direct summand of $R^n$, and hence as a finitely generated projective module. Prove that $I$ is free if and only if it is principal, and explain why it is free of rank one after localisation at every maximal ideal.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch06-gaussian}
In the Dedekind domain $S=\Z[i]$, factor the ideals $2S$, $3S$ and $5S$. Determine the residue fields, the ramification indices and the residue degrees in each case. Check $\sum ef=2$ directly, and explain why a repeated polynomial root produces one prime with multiplicity rather than two distinct primes.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:v10new-ch06-cusp}
Let $R=K[t^2,t^3]\subset K[t]$ for a field $K$, and $\mathfrak m=(t^2,t^3)$. Show that $R$ is a Noetherian one-dimensional domain and that $\mathfrak m$ is maximal. Verify $\mathfrak m^2=t^2\mathfrak m$, and use this equality to prove that $\mathfrak m$ is not invertible. Identify an integral element of the fraction field outside $R$. Which condition in Noether's Dedekind criterion does this example violate?
\end{exercise}

