\caption{Complements for the sign action of $\Z/2$ on $\Z$ are reflections $r\mapsto x-r$. Their mirrors lie at $x/2$. Conjugation by the translation $r\mapsto r+1$ replaces $x$ by $x+2$, so integer mirrors and half-integer mirrors give the two classes in $H^1\cong\Z/2$.}
\label{fig:v10new-ch08-complements}
\end{figure}

