theorem:
\begin{theorem}[Young, Frobenius, Specht]\label{thm:specht}
As $\lambda$ ranges over the partitions of $n$, the modules $S^\lambda$ are nonzero irreducible representations, pairwise nonisomorphic. Every irreducible representation of $\mathfrak S_n$ is isomorphic to exactly one of them.
\end{theorem}

\begin{theorem}\label{thm:standardbasis}
For fixed $\lambda$, the polytabloids $e_T$ with $T$ standard are linearly independent. Consequently $\dim S^\lambda\ge f^\lambda$.
\end{theorem}

\begin{theorem}[Schensted, 1961]\label{thm:schensted}
The first-row length of $P(\sigma)$ equals the length of a longest increasing subsequence of $\sigma(1),\ldots,\sigma(n)$.
\end{theorem}

\begin{theorem}[Hook length formula; Frame, Robinson and Thrall, 1954]\label{thm:hook}
For every partition $\lambda\vdash n$,
\[
f^\lambda=\frac{n!}{\prod_{(i,j)\in\lambda}h_{ij}}.
\]
\end{theorem}

\begin{theorem}[Frobenius, 1900]\label{thm:transposition}
Let $n\ge2$, $\lambda\vdash n$, and let $\tau\in\mathfrak S_n$ be a transposition. The character of $S^\lambda$ satisfies
\[
\frac{\chi^\lambda(\tau)}{f^\lambda}
=\frac1{\binom n2}
\left(\sum_i\binom{\lambda_i}2-\sum_j\binom{\lambda'_j}2\right)
=\frac1{\binom n2}\sum_{(i,j)\in\lambda}(j-i).
\]
\end{theorem}

lemma:
\begin{lemma}[Dominance lemma]\label{lem:dominance}
Let $T,T'$ have shapes $\lambda,\mu$. Suppose that the entries in each individual row of $T'$ lie in distinct columns of $T$. Then $\lambda\trianglerighteq\mu$.
\end{lemma}

\begin{lemma}\label{lem:kappa}
Let $T$ have shape $\lambda$ and $T'$ shape $\mu$.
\begin{enumerate}[label=(\alph*)]
\item If $\kappa_T\{T'\}\ne0$, then $\lambda\trianglerighteq\mu$.
\item If $\lambda=\mu$, then $\kappa_T\{T'\}$ is $0$, $e_T$ or $-e_T$. Thus $\kappa_Tu$ is a multiple of $e_T$ for every $u\in M^\lambda$.
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:insertion}
Row insertion produces another partial standard tableau and adds exactly one corner cell. As the insertion passes from one row to the next, its column weakly decreases. From the resulting tableau and the added corner, the previous tableau and the inserted entry are uniquely recoverable.
\end{lemma}

corollary:
\begin{corollary}\label{cor:conjugate}
For $n\ge2$, conjugating a partition negates its transposition-character ratio:
\[
\frac{\chi^{\lambda'}(\tau)}{f^{\lambda'}}
=-\frac{\chi^\lambda(\tau)}{f^\lambda}.
\]
For every $n\ge1$, $f^{\lambda'}=f^\lambda$.
\end{corollary}

definition:
\begin{definition}\label{def:standard}
A tableau is standard when its entries increase from left to right in every row and from top to bottom in every column. Write $f^\lambda$ for the number of standard tableaux of shape $\lambda$.
\end{definition}

\begin{definition}\label{def:hook}
The hook of $(i,j)$ consists of the cell itself, the cells to its right in row $i$ (the arm), and the cells below it in column $j$ (the leg). Its size is the hook length
\[
h_{ij}=\lambda_i-j+\lambda'_j-i+1.
\]
\end{definition}

exercise_blocks:
\begin{exercise}[$\star$]\label{ex:catalan}
For $n\ge1$, use hooks to prove $f^{(n,n)}=\binom{2n}n/(n+1)$. Give a direct bijection between these standard tableaux and correctly matched strings of $n$ opening and $n$ closing brackets. Include the empty string if you extend the formula to $n=0$.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:smalltables}
For every partition of $4$, calculate $f^\lambda$ and $\chi^\lambda(\tau)$ using hooks and contents. Match the results with Volume~3, Example~11.13. Then find the seven irreducible dimensions for $\mathfrak S_5$ and verify that their squares sum to $120$.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:standardrep}
For $n\ge2$, use the dominance observation after Theorem~\ref{thm:specht} and dimensions to show
$M^{(n-1,1)}\cong S^{(n)}\oplus S^{(n-1,1)}$.
You may establish the needed multiplicity-one fact directly as in Exercise~\ref{ex:youngmult}, or use the constant line and sum-zero hyperplane. Then prove
\[
f^{(n-j,j)}=\binom nj-\binom n{j-1}
\quad(0\le j\le\lfloor n/2\rfloor),
\]
with $\binom n{-1}=0$ and a zero final part omitted from the partition.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:youngmult}
Let $\mu\vdash n$. Prove that every module map $S^\mu\to M^\mu$ is a scalar multiple of the inclusion. Deduce that $S^\mu$ occurs exactly once in $M^\mu$, while every other constituent $S^\lambda$ satisfies $\lambda\triangleright\mu$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:patience}
Deal a permutation's entries in order onto piles. Place each entry on the leftmost pile with a larger top, or start a new pile on the right if there is none. Prove that each pile, read from bottom to top, is a decreasing subsequence; that the pile tops are the first row of $P$; and that the number of piles equals the longest increasing-subsequence length. Deduce that every sequence of $rs+1$ distinct numbers has an increasing subsequence of length $r+1$ or a decreasing one of length $s+1$, for positive integers $r,s$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:frobeniusdim}
For $\lambda=(\lambda_1,\ldots,\lambda_k)$, put $l_i=\lambda_i+k-i$. Prove that the hooks in row $i$ are exactly $1,\ldots,l_i$ with the numbers $l_i-l_j$ for $j>i$ deleted. Conclude that
\[
f^\lambda=\frac{n!\prod_{i<j}(l_i-l_j)}{l_1!\cdots l_k!}.
\]
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch10-standardcharacter}
For $n\ge2$, compute the character of $S^{(n-1,1)}$ at an arbitrary permutation in terms of its fixed points. With the basis $v_a=\mathbf e_a-\mathbf e_n$ for $a<n$, compute the Gram matrix for the ordinary Hermitian product and the action of $(1\,n)$. Check its trace against your character formula, including $n=2$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch10-hookwalk}
For shape $(3,1)$, compute the probability of stopping at each corner from each of the four possible starting cells. Average to recover Figure~\ref{fig:v10new-ch10-hookprob}. Use the same method for shape $(2,2)$ and explain why the only corner has probability $1$ although several paths can reach it.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch10-plancherel4}
For a uniform permutation of four entries, find the complete distribution of its longest increasing-subsequence length using Robinson--Schensted and the five dimensions from Exercise~\ref{ex:smalltables}. Compute its expectation. Find the probability that its insertion shape is self-conjugate, and explain why a self-conjugate shape has zero transposition character.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:v10new-ch10-collisions}
List the content sums and dimensions for all partitions of $6$. Show that the transposition-averaging operator has eigenvalue $1/5$ with total multiplicity $125$. Explain why a statement giving its multiplicity as $(f^\lambda)^2$ for just one partition can be false. Give the multiplicity of $-1/5$ too, without repeating every hook calculation.
\end{exercise}

