theorem:
\begin{theorem}[Schur orthogonality]\label{thm:schurorth}
Choose one unitary representative of each isomorphism class of irreducible representations. If $\rho,\sigma$ are two of these representatives, then
\[
\int_G\rho_{ij}(g)\overline{\sigma_{kl}(g)}\,\dd\mu(g)
=\begin{cases}
 d_\rho^{-1}\delta_{ik}\delta_{jl},&\rho=\sigma,\\
 0,&\rho\not\cong\sigma,
\end{cases}
\]
where $d_\rho=\dim V_\rho$. In particular, the irreducible characters $\chi_\rho=\operatorname{tr}\rho$ are orthonormal in $L^2(G,\mu)$. Two finite-dimensional representations with the same character are isomorphic.
\end{theorem}

\begin{theorem}[Weyl's character formula for $U(n)$, 1925]\label{thm:weylchar}
For each dominant weight $\lambda$, there is an irreducible representation $V_\lambda$ of $U(n)$ with character $s_\lambda$ on $T$. Every irreducible representation occurs for exactly one dominant weight. Its dimension is
\[
\dim V_\lambda=s_\lambda(1,\ldots,1)
=\prod_{1\le j<k\le n}
\frac{\lambda_j-\lambda_k+k-j}{k-j}.
\]
\end{theorem}

proposition:
\begin{proposition}\label{prop:unitarytrick}
For every representation of $G$, there is an inner product on its space for which the representation is unitary. Every such representation is a direct sum of irreducible representations.
\end{proposition}

lemma:
\begin{lemma}\label{lem:alternants}
\begin{enumerate}[label=(\alph*)]
\item Each $s_\lambda$ is a symmetric Laurent polynomial with integer coefficients. In lexicographic order its largest monomial is $t^\lambda$, with coefficient $1$.
\item Every antisymmetric Laurent polynomial has a unique finite expression $\sum_\mu c_\mu a_\mu$ over strictly decreasing integer vectors $\mu$. Here $c_\mu$ is its coefficient of $t^\mu$.
\item If $\mu,\nu$ are strictly decreasing, then
\[
\frac1{n!}\int_T a_\mu(t)\overline{a_\nu(t)}\,
\frac{\dd\theta_1\cdots\dd\theta_n}{(2\pi)^n}
=\delta_{\mu\nu}.
\]
\end{enumerate}
\end{lemma}

\begin{lemma}[Pieri's rule for one box]\label{lem:pieri}
If $\lambda$ is dominant, then
$p_1s_\lambda=\sum_\nu s_\nu$, where $\nu$ runs over dominant weights obtained by adding $1$ to one entry of $\lambda$.
\end{lemma}

corollary:
\begin{corollary}\label{cor:gaussiantrace}
As $n\to\infty$, $\sqrt2\operatorname{Re}\operatorname{tr}U$ converges in distribution to $N(0,1)$. For every fixed real $\phi$, the same is true of $\sqrt2\operatorname{Re}(e^{-i\phi}\operatorname{tr}U)$.
\end{corollary}

definition:
\begin{definition}\label{def:schurpoly}
For a dominant weight $\lambda$, its Schur function is
$s_\lambda=a_{\lambda+\delta}/a_\delta$.
The quotient is first read where the coordinates are distinct, then extended by its Laurent-polynomial expression.
\end{definition}

exercise_blocks:
\begin{exercise}[$\star$]\label{ex:dims}
For $n\ge1$ and integer $k\ge0$, compute $\dim\operatorname{Sym}^k\C^n$ with Theorem~\ref{thm:weylchar}. Compute $\dim\Lambda^k\C^n$ for $0\le k\le n$. For $n\ge2$, compute the dimension of $V_{(1,0,\ldots,0,-1)}$ and identify it in $\operatorname{End}(\C^n)\cong\C^n\otimes\overline{\C^n}$, with the conjugation action.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:tensorsquare}
Take $n\ge2$. Prove
$s_{(1,0,\ldots,0)}^2=s_{(2,0,\ldots,0)}+s_{(1,1,0,\ldots,0)}$.
Use it to identify the two irreducible summands in
$\C^n\otimes\C^n=\operatorname{Sym}^2\C^n\oplus\Lambda^2\C^n$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:charpoly}
Express $\det(I-U)$ as $\sum_{k=0}^n(-1)^k\chi_{\Lambda^k}(U)$. Use orthogonality to prove $\mathbb E|\det(I-U)|^2=n+1$ for Haar $U\in U(n)$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:su2}
Let $m$ be a nonnegative integer. Restrict $V_{(m,0)}$ to $SU(2)$. Show that its character at eigenvalues $e^{\pm i\alpha}$ is
$\chi_m(\alpha)=\sin((m+1)\alpha)/\sin\alpha$, with continuous values at $0$ and $\pi$. Use the density $(2/\pi)\sin^2\alpha$ on $[0,\pi]$ from Volume~9, Exercise~8.3 to prove these representations are irreducible, pairwise non-isomorphic, and exhaust the irreducible representations of $SU(2)$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:catalanu2}
For Haar $U\in U(2)$ and integer $a\ge0$, evaluate $\mathbb E|\operatorname{tr}U|^{2a}$ directly from Weyl integration. Combine it with Theorem~\ref{thm:traces} to count permutations of $\{1,\ldots,a\}$ with no increasing subsequence of length $3$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:domino}
Prove $p_2s_\lambda=\sum_\nu\pm s_\nu$. The sum is over dominant weights obtained by a domino addition: raise two adjacent equal row lengths by $1$ (a vertical domino, sign $-$), or raise one row length by $2$ (a horizontal domino, sign $+$), keeping the resulting vector dominant. For a general integer dominant weight, first shift every entry by the same integer to draw its partition diagram. This is the two-box case of the Murnaghan--Nakayama rule.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch11-statistic}
Let $f(z)=\sum_{k=-M}^M c_kz^k$ be a Laurent polynomial and $U\in U(n)$ Haar. Define $L_f(U)=\sum_{j=1}^n f(t_j)$ from its eigenvalues. Find $\mathbb E L_f$ and $\mathbb E|L_f-\mathbb E L_f|^2$. Compare the answer with $n$ independent uniform circle points, and compute it for $f(e^{i\theta})=\cos\theta+2\cos2\theta$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch11-detmoment}
For integers $r$ and nonnegative integers $a,b$, prove
$\mathbb E[(\det U)^r(\operatorname{tr}U)^a\overline{\operatorname{tr}U}^b]=0$
unless $nr+a-b=0$. Decide whether this condition also guarantees a nonzero expectation, using the tableau expansion of trace powers. Compute $\mathbb E[\overline{\det U}(\operatorname{tr}U)^n]$ and explain the answer using the one-column tableau.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:v10new-ch11-projective}
The projective unitary group is $PU(n)=U(n)/\{zI:|z|=1\}$. Prove that $V_\lambda$ factors through this quotient exactly when $\sum_j\lambda_j=0$. Given a partition $\mu$, determine when a determinant twist $\det^r\otimes V_\mu$ factors through $PU(n)$, and find $r$. Check the standard representation and the trace-zero conjugation representation for $n\ge2$.
\end{exercise}

hint_blocks:
\begin{hint}{ex:dims}
Most factors of the dimension product equal $1$. Separate the pairs touching the first or last row. For the final identification, split scalar matrices from trace-zero matrices and inspect the largest torus weight.
\end{hint}

\begin{hint}{ex:tensorsquare}
Add one box to $(1)$ using Pieri's rule. The flip of two tensor factors has eigenspaces $\operatorname{Sym}^2$ and $\Lambda^2$.
\end{hint}

\begin{hint}{ex:charpoly}
Expand $\prod_j(1-t_j)$. The elementary symmetric functions are distinct irreducible characters, including the constant character at $k=0$.
\end{hint}

\begin{hint}{ex:su2}
Substitute $t_1=e^{i\alpha}$ and $t_2=e^{-i\alpha}$ into the two-variable alternant. Multiplication by $\sin\alpha$ turns the weighted character inner product into the ordinary sine-series inner product.
\end{hint}

\begin{hint}{ex:catalanu2}
Use $\varphi=\theta_1-\theta_2$. Then $|t_1+t_2|^2=4\cos^2(\varphi/2)$ and $|t_1-t_2|^2=4\sin^2(\varphi/2)$. Subtract two consecutive Wallis integrals.
\end{hint}

\begin{hint}{ex:domino}
Multiply the alternant by $p_2$, raising one exponent by $2$. A collision makes the term zero. Crossing one neighbouring exponent changes the sign.
\end{hint}

\begin{hint}{ex:v10new-ch11-statistic}
Put $p_k=\operatorname{tr}U^k$ for all nonzero integers $k$; then $p_{-k}=\overline{p_k}$. Rotation makes distinct signed frequencies perpendicular.
\end{hint}

\begin{hint}{ex:v10new-ch11-detmoment}
Replace $U$ by $zU$. For the requested value, take the character inner product of $p_1^n$ with $\det$ and apply the tableau expansion.
\end{hint}

\begin{hint}{ex:v10new-ch11-projective}
The central scalar $zI$ acts by a scalar on an irreducible representation. Evaluate its character using the homogeneity of the alternant quotient. A representation descends precisely when that scalar is always $1$.
\end{hint}

\begin{hint}{ex:v10new-ch11-firstfailure}
Among permutations of $n+1$ letters, how many have an increasing subsequence of length $n+1$? Apply Markov's inequality to the nonnegative variable $|X_n|^{2r}$ for the tail estimate.
\end{hint}

solution_blocks:
\begin{solution}{ex:tensorsquare}
\idea Pieri's two possible additions match the symmetric and alternating pieces.
\writeup Adding a box to $(1)$ gives $(2)$ or $(1,1)$, since $n\ge2$. Thus $p_1^2=s_{(2)}+s_{(1,1)}$. The tensor square has this character, so it is the direct sum of these two irreducibles.

The flip $v\otimes w\mapsto w\otimes v$ commutes with $U(n)$. Its $+1$ and $-1$ eigenspaces give the symmetric and exterior squares; the projections are half the identity plus or minus half the flip. Both spaces are nonzero. Since there are only two irreducible constituents in total, each is irreducible. The weight $t_1^2$, represented by $e_1\otimes e_1$, occurs in the symmetric square and not in the exterior square. It distinguishes $V_{(2)}$ from $V_{(1,1)}$ and makes the identification precise.
\end{solution}

\begin{solution}{ex:v10new-ch11-firstfailure}
\idea The first missing tableau count measures the first missing Gaussian radial moment. A low moment still gives a valid tail bound.
\writeup A permutation of $n+1$ letters has an increasing subsequence of length $n+1$ exactly when the whole permutation is increasing. There is one such permutation. Theorem~\ref{thm:traces} therefore gives $(n+1)!-1$. At $n=1$, this reads $\mathbb E|U|^4=1=2!-1$, a useful boundary check.

For $1\le r\le n$, the exact moment is $\mathbb E|X_n|^{2r}=r!$. Markov's inequality applied to $|X_n|^{2r}$ gives $P(|X_n|\ge t)\le r!/t^{2r}$. The bound can be replaced by its minimum with $1$; it need not be sharp.

A standard complex Gaussian $Z$, with planar density $\pi^{-1}e^{-|z|^2}$, has $\mathbb E|Z|^{2a}=a!$ by polar integration and the gamma integral. The first displayed moment differs from that Gaussian value by $1$. Moreover $|X_n|\le n$ while $Z$ has positive probability outside every finite disc. Thus finite agreement of many moments does not imply equality of distributions. As $n$ grows, any fixed moment eventually lies in the exact-agreement range, which is why a limiting Gaussian law remains possible.
\end{solution}

